CREATE SCHEMA problem;
CREATE TABLE problem.problems (id uuid PRIMARY KEY, tenant_id text NOT NULL, code text NOT NULL, title text NOT NULL, state text NOT NULL DEFAULT 'NEW', root_cause text, workaround text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, code), CHECK (state IN ('NEW','UNDER_REVIEW','INVESTIGATING','WORKAROUND_AVAILABLE','KNOWN_ERROR','FIX_IN_PROGRESS','VERIFYING_FIX','RESOLVED','CLOSED','CANCELLED')));
CREATE TABLE problem.changes (id uuid PRIMARY KEY, tenant_id text NOT NULL, code text NOT NULL, title text NOT NULL, state text NOT NULL DEFAULT 'DRAFT', risk text, impact text, implementation_plan text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, code), CHECK (state IN ('DRAFT','ASSESSMENT','PENDING_APPROVAL','APPROVED','SCHEDULED','IMPLEMENTING','VERIFYING','COMPLETED','FAILED','ROLLED_BACK','CLOSED','CANCELLED')));
CREATE TABLE problem.knowledge_articles (id uuid PRIMARY KEY, tenant_id text NOT NULL, slug text NOT NULL, title text NOT NULL, body text NOT NULL, state text NOT NULL DEFAULT 'DRAFT', version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, slug), CHECK (state IN ('DRAFT','IN_REVIEW','PUBLISHED','ARCHIVED')));
CREATE INDEX problem_state_lookup ON problem.problems(tenant_id,state); CREATE INDEX change_state_lookup ON problem.changes(tenant_id,state); CREATE INDEX knowledge_state_lookup ON problem.knowledge_articles(tenant_id,state);
